import { create_list_delete_tags } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    editTagDialog: Boolean,
    rowInfo: Object
  },
  data() {
    return {
      loading: false,
      assetTagName: "",
      tagSelection: []
    };
  },
  watch: {
    editTagDialog: {
      async handler() {
        this.assetTagName = "";
        this.tagSelection = [];
        this.assetTagName = this.rowInfo.tag_name;
        this.tagSelection = this.rowInfo.sub_tags;
      },
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
      this.assetTagName = "";
      this.tagSelection = [];
    },
    removecc(item) {
      this.tagSelection.splice(this.tagSelection.indexOf(item), 1);
    },
    validate_data() {
      if (this.$refs.form.validate()) {
        this.edit_mutation();
      }
    },
    async edit_mutation() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(create_list_delete_tags, {
          input: {
            user_email_id: data.user.user_email_id,
            action_type: "UPDATE_TAGS",
            tag_name: this.assetTagName,
            sub_tag: JSON.stringify(this.tagSelection),
            tag_id: this.rowInfo.tag_id
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.create_list_delete_tags);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
          this.assetTagName = "";
          this.tagSelection = [];
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    }
  }
};
